1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
3	
4	const ALLOWED_ORIGINS = [
5	  Deno.env.get("APP_URL") || "https://rankora.co",
6	  "https://www.rankora.co",
7	  "http://localhost:8080",
8	  "http://localhost:5173",
9	];
10	
11	function getCorsOrigin(req: Request): string {
12	  const origin = req.headers.get("origin") || "";
13	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
14	}
15	
16	// In-memory rate limit — simple sliding window per (user_id || ip).
17	// Edge functions run isolated per instance, so this is best-effort,
18	// not a hard quota. Real rate limiting should be handled upstream by
19	// Cloudflare or a dedicated service.
20	const rateLimitMap = new Map<string, number[]>();
21	const MAX_PER_MINUTE = 30;
22	const WINDOW_MS = 60_000;
23	
24	function isRateLimited(key: string): boolean {
25	  const now = Date.now();
26	  const timestamps = rateLimitMap.get(key) ?? [];
27	  const recent = timestamps.filter((t) => now - t < WINDOW_MS);
28	  if (recent.length >= MAX_PER_MINUTE) return true;
29	  recent.push(now);
30	  rateLimitMap.set(key, recent);
31	  // Periodic cleanup of stale keys. Tighter than before: trigger at
32	  // 500 entries with 5% probability so the map never balloons far
33	  // beyond a few hundred active keys per instance. Deno edge
34	  // functions isolate state per instance, so this only protects the
35	  // per-instance working set — real rate limiting would require a
36	  // shared store (Supabase table, Redis, or Cloudflare KV).
37	  if (rateLimitMap.size > 500 && Math.random() < 0.05) {
38	    for (const [k, ts] of rateLimitMap.entries()) {
39	      if (!ts.some((t) => now - t < WINDOW_MS)) rateLimitMap.delete(k);
40	    }
41	  }
42	  return false;
43	}
44	
45	serve(async (req) => {
46	  const corsHeaders = {
47	    "Access-Control-Allow-Origin": getCorsOrigin(req),
48	    "Access-Control-Allow-Headers":
49	      "authorization, x-client-info, apikey, content-type",
50	  };
51	
52	  if (req.method === "OPTIONS")
53	    return new Response(null, { headers: corsHeaders });
54	
55	  if (req.method !== "POST") {
56	    return new Response(JSON.stringify({ ok: false, reason: "method" }), {
57	      status: 405,
58	      headers: { ...corsHeaders, "Content-Type": "application/json" },
59	    });
60	  }
61	
62	  try {
63	    // Resolve the caller's identity from their Supabase auth token.
64	    // Trust NOTHING from the request body for user attribution.
65	    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
66	    const supabaseAnon = Deno.env.get("SUPABASE_ANON_KEY")!;
67	    const authHeader = req.headers.get("authorization") || "";
68	    let authedUserId: string | null = null;
69	    if (authHeader.startsWith("Bearer ")) {
70	      try {
71	        const authClient = createClient(supabaseUrl, supabaseAnon, {
72	          global: { headers: { Authorization: authHeader } },
73	        });
74	        const {
75	          data: { user },
76	        } = await authClient.auth.getUser();
77	        authedUserId = user?.id ?? null;
78	      } catch {
79	        // Anonymous caller — fall through, user_id stays null
80	      }
81	    }
82	
83	    // Rate limit by authed user if present, else by client IP
84	    const ip =
85	      req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
86	      req.headers.get("cf-connecting-ip") ||
87	      "unknown";
88	    const rateKey = authedUserId ?? `ip:${ip}`;
89	    if (isRateLimited(rateKey)) {
90	      return new Response(
91	        JSON.stringify({ ok: false, reason: "rate_limited" }),
92	        {
93	          status: 429,
94	          headers: { ...corsHeaders, "Content-Type": "application/json" },
95	        },
96	      );
97	    }
98	
99	    // Cap request body at 16KB to prevent log spam via huge payloads
100	    const contentLength = Number(req.headers.get("content-length") || "0");
101	    if (contentLength > 16_384) {
102	      return new Response(
103	        JSON.stringify({ ok: false, reason: "payload_too_large" }),
104	        {
105	          status: 413,
106	          headers: { ...corsHeaders, "Content-Type": "application/json" },
107	        },
108	      );
109	    }
110	
111	    const body = await req.json();
112	    const {
113	      error_type,
114	      function_name,
115	      severity = "warning",
116	      error_message,
117	      error_stack,
118	      context_json,
119	    } = body;
120	
121	    if (!error_message) {
122	      return new Response(
123	        JSON.stringify({ ok: false, reason: "missing error_message" }),
124	        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
125	      );
126	    }
127	
128	    const serviceClient = createClient(
129	      supabaseUrl,
130	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
131	    );
132	
133	    // Dedup: skip if same error (same message + source) was logged in the last 5 minutes
134	    const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
135	    const { data: existing } = await serviceClient
136	      .from("system_error_logs")
137	      .select("id")
138	      .eq("error_message", String(error_message).slice(0, 500))
139	      .eq("function_name", function_name ?? "frontend")
140	      .gte("created_at", fiveMinAgo)
141	      .limit(1);
142	
143	    if (existing && existing.length > 0) {
144	      return new Response(JSON.stringify({ ok: true, deduped: true }), {
145	        headers: { ...corsHeaders, "Content-Type": "application/json" },
146	      });
147	    }
148	
149	    // Strip HTML tags to prevent stored-XSS into the admin panel viewer
150	    const safeMessage = String(error_message)
151	      .replace(/<[^>]*>/g, "")
152	      .slice(0, 2000);
153	    const safeStack = error_stack
154	      ? String(error_stack).replace(/<[^>]*>/g, "").slice(0, 5000)
155	      : null;
156	
157	    await serviceClient.from("system_error_logs").insert({
158	      function_name: (function_name ?? "frontend").slice(0, 100),
159	      error_type: (error_type ?? "ClientError").slice(0, 100),
160	      severity: ["critical", "warning", "info"].includes(severity)
161	        ? severity
162	        : "warning",
163	      error_message: safeMessage,
164	      error_stack: safeStack,
165	      context_json: context_json ?? {},
166	      // user_id is taken from the verified auth token — body value ignored
167	      user_id: authedUserId,
168	      is_resolved: false,
169	    });
170	
171	    return new Response(JSON.stringify({ ok: true }), {
172	      headers: { ...corsHeaders, "Content-Type": "application/json" },
173	    });
174	  } catch {
175	    return new Response(JSON.stringify({ ok: false }), {
176	      status: 500,
177	      headers: { ...corsHeaders, "Content-Type": "application/json" },
178	    });
179	  }
180	});
