1	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
2	import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
3	
4	const ALLOWED_ORIGINS = [
5	  Deno.env.get("APP_URL") || "https://rankora.co",
6	  "https://www.rankora.co",
7	  "http://localhost:8080",
8	  "http://localhost:5173",
9	];
10	
11	function getCorsOrigin(req: Request): string {
12	  const origin = req.headers.get("origin") || "";
13	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
14	}
15	
16	Deno.serve(async (req) => {
17	  const corsHeaders = {
18	    "Access-Control-Allow-Origin": getCorsOrigin(req),
19	    "Access-Control-Allow-Headers":
20	      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
21	  };
22	  if (req.method === "OPTIONS") {
23	    return new Response(null, { headers: corsHeaders });
24	  }
25	
26	  // Cron-secret gate: this endpoint uses service role and mutates
27	  // subscription state. Only accept requests that carry the shared
28	  // CRON_SECRET. Reject everything else with 401.
29	  const cronSecret = Deno.env.get("CRON_SECRET");
30	  const authHeader = req.headers.get("authorization") || "";
31	  const providedSecret = authHeader.startsWith("Bearer ")
32	    ? authHeader.slice(7).trim()
33	    : "";
34	  if (!cronSecret || providedSecret !== cronSecret) {
35	    return new Response(JSON.stringify({ error: "Unauthorized" }), {
36	      status: 401,
37	      headers: { ...corsHeaders, "Content-Type": "application/json" },
38	    });
39	  }
40	
41	  try {
42	    const serviceClient = createClient(
43	      Deno.env.get("SUPABASE_URL")!,
44	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
45	    );
46	
47	    // Find all profiles with expired subscriptions that are still on a paid plan
48	    const { data: expired, error } = await serviceClient
49	      .from("profiles")
50	      .select("id, user_id, plan, subscription_ends_at")
51	      .neq("plan", "free")
52	      .not("subscription_ends_at", "is", null)
53	      .lt("subscription_ends_at", new Date().toISOString());
54	
55	    if (error) {
56	      console.error("Query error:", error.message);
57	      await logSystemError({
58	        function_name: "check-expired-subscriptions",
59	        error_type: "QUERY_ERROR",
60	        severity: "critical",
61	        error_message: `Query error: ${error.message}`,
62	      });
63	      return new Response(JSON.stringify({ error: error.message }), {
64	        status: 500,
65	        headers: { ...corsHeaders, "Content-Type": "application/json" },
66	      });
67	    }
68	
69	    if (!expired || expired.length === 0) {
70	      return new Response(JSON.stringify({ downgraded: 0 }), {
71	        headers: { ...corsHeaders, "Content-Type": "application/json" },
72	      });
73	    }
74	
75	    // Downgrade all expired users to free/PAYG
76	    const userIds = expired.map((p) => p.user_id);
77	    const { error: updateError } = await serviceClient
78	      .from("profiles")
79	      .update({ plan: "free", subscription_ends_at: null, dodo_subscription_id: null })
80	      .in("user_id", userIds);
81	
82	    if (updateError) {
83	      console.error("Update error:", updateError.message);
84	      await logSystemError({
85	        function_name: "check-expired-subscriptions",
86	        error_type: "UPDATE_ERROR",
87	        severity: "critical",
88	        error_message: `Update error: ${updateError.message}`,
89	      });
90	      return new Response(JSON.stringify({ error: updateError.message }), {
91	        status: 500,
92	        headers: { ...corsHeaders, "Content-Type": "application/json" },
93	      });
94	    }
95	
96	    console.log(`Auto-downgraded ${expired.length} expired subscriptions`);
97	
98	    return new Response(
99	      JSON.stringify({ downgraded: expired.length, user_ids: userIds }),
100	      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
101	    );
102	  } catch (err: unknown) {
103	    console.error("Error:", err);
104	    await logSystemError({
105	      function_name: "check-expired-subscriptions",
106	      error_type: "SUBSCRIPTION_EXPIRY_ERROR",
107	      severity: "critical",
108	      error_message: errorToMessage(err),
109	      error_stack: errorToStack(err),
110	    });
111	    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
112	      status: 500,
113	      headers: { ...corsHeaders, "Content-Type": "application/json" },
114	    });
115	  }
116	});
