1	import "jsr:@supabase/functions-js/edge-runtime.d.ts";
2	import { createClient } from "jsr:@supabase/supabase-js@2";
3	
4	// ── Fix H2/H3: Replace CORS wildcard with allowlist ──────────────────────────
5	const ALLOWED_ORIGINS = [
6	  Deno.env.get("APP_URL") || "https://rankora.co",
7	  "https://www.rankora.co",
8	  "http://localhost:8080",
9	  "http://localhost:5173",
10	];
11	
12	function getCorsOrigin(req: Request): string {
13	  const origin = req.headers.get("origin") || "";
14	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
15	}
16	
17	function getCorsHeaders(req: Request) {
18	  return {
19	    "Access-Control-Allow-Origin": getCorsOrigin(req),
20	    "Access-Control-Allow-Headers":
21	      "authorization, x-client-info, apikey, content-type",
22	  };
23	}
24	
25	Deno.serve(async (req) => {
26	  const cors = getCorsHeaders(req);
27	
28	  if (req.method === "OPTIONS") {
29	    return new Response("ok", { headers: cors });
30	  }
31	
32	  try {
33	    // ── Auth ──────────────────────────────────────────────────────────────────
34	    const authHeader = req.headers.get("Authorization");
35	    if (!authHeader) {
36	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
37	        status: 401,
38	        headers: { ...cors, "Content-Type": "application/json" },
39	      });
40	    }
41	
42	    const supabase = createClient(
43	      Deno.env.get("SUPABASE_URL")!,
44	      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
45	    );
46	
47	    const token = authHeader.replace("Bearer ", "");
48	    const {
49	      data: { user },
50	      error: authError,
51	    } = await supabase.auth.getUser(token);
52	
53	    if (authError || !user) {
54	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
55	        status: 401,
56	        headers: { ...cors, "Content-Type": "application/json" },
57	      });
58	    }
59	
60	    // ── Validate input ────────────────────────────────────────────────────────
61	    const body = await req.json() as {
62	      job_id?: string;
63	      source_resume_ids?: string[];
64	    };
65	
66	    const { job_id, source_resume_ids } = body;
67	
68	    if (!job_id || typeof job_id !== "string") {
69	      return new Response(JSON.stringify({ error: "job_id is required" }), {
70	        status: 400,
71	        headers: { ...cors, "Content-Type": "application/json" },
72	      });
73	    }
74	
75	    if (
76	      !source_resume_ids ||
77	      !Array.isArray(source_resume_ids) ||
78	      source_resume_ids.length === 0
79	    ) {
80	      return new Response(
81	        JSON.stringify({ error: "source_resume_ids must be a non-empty array" }),
82	        {
83	          status: 400,
84	          headers: { ...cors, "Content-Type": "application/json" },
85	        },
86	      );
87	    }
88	
89	    if (source_resume_ids.length > 20) {
90	      return new Response(
91	        JSON.stringify({ error: "Cannot import more than 20 resumes at once" }),
92	        {
93	          status: 400,
94	          headers: { ...cors, "Content-Type": "application/json" },
95	        },
96	      );
97	    }
98	
99	    // ── Verify target job ownership ───────────────────────────────────────────
100	    const { data: targetJob, error: targetJobError } = await supabase
101	      .from("jobs")
102	      .select("id, user_id, status")
103	      .eq("id", job_id)
104	      .single();
105	
106	    if (targetJobError || !targetJob) {
107	      return new Response(JSON.stringify({ error: "Target job not found" }), {
108	        status: 404,
109	        headers: { ...cors, "Content-Type": "application/json" },
110	      });
111	    }
112	
113	    if (targetJob.user_id !== user.id) {
114	      return new Response(JSON.stringify({ error: "Forbidden" }), {
115	        status: 403,
116	        headers: { ...cors, "Content-Type": "application/json" },
117	      });
118	    }
119	
120	    // ── Fetch source resumes (verify ownership via jobs join) ─────────────────
121	    const { data: sourceResumes, error: sourceError } = await supabase
122	      .from("resumes")
123	      .select(
124	        "id, job_id, filename, file_path, candidate_name, parsed_json, parsed_text, embedding, status, source",
125	      )
126	      .in("id", source_resume_ids)
127	      .eq("status", "done");
128	
129	    if (sourceError) {
130	      console.error("Failed to fetch source resumes:", sourceError);
131	      throw new Error("Failed to fetch source resumes");
132	    }
133	
134	    if (!sourceResumes || sourceResumes.length === 0) {
135	      return new Response(
136	        JSON.stringify({ error: "No valid source resumes found" }),
137	        {
138	          status: 404,
139	          headers: { ...cors, "Content-Type": "application/json" },
140	        },
141	      );
142	    }
143	
144	    // Verify all source resumes belong to the same user (via their original job)
145	    const sourceJobIds = [...new Set(sourceResumes.map((r: { job_id: string }) => r.job_id))];
146	    const { data: sourceJobs, error: sourceJobsError } = await supabase
147	      .from("jobs")
148	      .select("id, user_id")
149	      .in("id", sourceJobIds);
150	
151	    if (sourceJobsError) throw new Error("Failed to verify source job ownership");
152	
153	    const unauthorizedJobs = (sourceJobs ?? []).filter(
154	      (j: { id: string; user_id: string }) => j.user_id !== user.id,
155	    );
156	    if (unauthorizedJobs.length > 0) {
157	      return new Response(JSON.stringify({ error: "Forbidden: some resumes do not belong to you" }), {
158	        status: 403,
159	        headers: { ...cors, "Content-Type": "application/json" },
160	      });
161	    }
162	
163	    // ── Fix H4: Deduplicate by email (not file_path) ─────────────────────────
164	    // Fetch existing resumes in the target job and extract their emails from parsed_json
165	    const { data: existingResumes } = await supabase
166	      .from("resumes")
167	      .select("parsed_json")
168	      .eq("job_id", job_id);
169	
170	    const existingEmails = new Set<string>(
171	      (existingResumes ?? [])
172	        .map((r: { parsed_json: unknown }) => {
173	          try {
174	            const p = r.parsed_json as Record<string, unknown> | null;
175	            const email = p?.email ?? p?.contact?.email ?? p?.personal?.email;
176	            return typeof email === "string" ? email.toLowerCase().trim() : null;
177	          } catch {
178	            return null;
179	          }
180	        })
181	        .filter((e): e is string => e !== null && e.length > 0),
182	    );
183	
184	    type SourceResume = {
185	      id: string;
186	      job_id: string;
187	      filename: string;
188	      file_path: string;
189	      candidate_name: string | null;
190	      parsed_json: unknown;
191	      parsed_text: string | null;
192	      embedding: unknown;
193	      status: string;
194	    };
195	
196	    const toImport = (sourceResumes as SourceResume[]).filter((r) => {
197	      try {
198	        const p = r.parsed_json as Record<string, unknown> | null;
199	        const email = p?.email ?? p?.contact?.email ?? p?.personal?.email;
200	        if (typeof email === "string" && email.length > 0) {
201	          return !existingEmails.has(email.toLowerCase().trim());
202	        }
203	      } catch {
204	        // No email in parsed_json — fall through and allow import
205	      }
206	      return true; // If no email, import by default (no dedup possible)
207	    });
208	
209	    if (toImport.length === 0) {
210	      return new Response(
211	        JSON.stringify({
212	          imported: [],
213	          skipped: source_resume_ids.length,
214	          message: "All selected candidates are already in this job",
215	        }),
216	        { headers: { ...cors, "Content-Type": "application/json" } },
217	      );
218	    }
219	
220	    // ── Fix C2: Deduct credits before inserting resume rows ───────────────────
221	    const { data: creditOk } = await supabase.rpc("deduct_credits", {
222	      _user_id: user.id,
223	      _job_id: job_id,
224	      _amount: toImport.length,
225	    });
226	
227	    if (!creditOk) {
228	      return new Response(
229	        JSON.stringify({ error: "Insufficient credits" }),
230	        {
231	          status: 402,
232	          headers: { ...cors, "Content-Type": "application/json" },
233	        },
234	      );
235	    }
236	
237	    // ── Insert cloned resume rows ─────────────────────────────────────────────
238	    const newRows = toImport.map((r) => ({
239	      job_id: job_id,
240	      filename: r.filename,
241	      file_path: r.file_path,
242	      candidate_name: r.candidate_name,
243	      parsed_json: r.parsed_json,
244	      parsed_text: r.parsed_text,
245	      embedding: r.embedding,
246	      status: "done", // already parsed — ready for ranking
247	      // Preserve the original source if available; otherwise tag as rediscovery
248	      source: (r as { source?: string }).source ?? "upload",
249	    }));
250	
251	    const { data: inserted, error: insertError } = await supabase
252	      .from("resumes")
253	      .insert(newRows)
254	      .select("id, filename, candidate_name");
255	
256	    if (insertError) {
257	      console.error("Failed to insert cloned resumes:", insertError);
258	      throw new Error("Failed to import resumes");
259	    }
260	
261	    const importedIds = (inserted ?? []).map((r: { id: string }) => r.id);
262	    const skippedCount = sourceResumes.length - toImport.length;
263	
264	    // ── Fix H1: Trigger ranking via fire-and-forget (rank-resumes supports resume_ids) ──
265	    if (importedIds.length > 0) {
266	      const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
267	      const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
268	
269	      // rank-resumes accepts resume_ids for targeted ranking.
270	      // Pass _internal + _user_id to bypass the top-level auth + credit check
271	      // (credits were already deducted above).
272	      fetch(`${supabaseUrl}/functions/v1/rank-resumes`, {
273	        method: "POST",
274	        headers: {
275	          "Authorization": `Bearer ${serviceKey}`,
276	          "Content-Type": "application/json",
277	        },
278	        body: JSON.stringify({
279	          job_id: job_id,
280	          resume_ids: importedIds,
281	          _internal: true,
282	          _user_id: user.id,
283	          _all_target_ids: importedIds,
284	        }),
285	      }).catch((err) => {
286	        console.error("Failed to trigger ranking for imported resumes:", err);
287	      });
288	    }
289	
290	    return new Response(
291	      JSON.stringify({
292	        imported: inserted ?? [],
293	        skipped: skippedCount,
294	        message: `${importedIds.length} candidate${importedIds.length !== 1 ? "s" : ""} imported. Ranking in progress.`,
295	      }),
296	      { headers: { ...cors, "Content-Type": "application/json" } },
297	    );
298	  } catch (error: unknown) {
299	    const message = error instanceof Error ? error.message : "Unknown error";
300	    console.error("import-rediscovered error:", message);
301	    return new Response(JSON.stringify({ error: message }), {
302	      status: 500,
