23	// ── Text quality validation ─────────────────────────────────
24	function isQualityText(text: string): boolean {
25	  if (!text || text.trim().length < 30) return false;
26	  const words = text.split(/\s+/).filter(w => /^[a-zA-Z]{2,}$/.test(w));
27	  const totalWords = text.split(/\s+/).length;
28	  const wordRatio = words.length / Math.max(totalWords, 1);
29	
30	  // Relaxed threshold for longer texts
31	  if (text.length > 500 && wordRatio > 0.2 && words.length > 15) return true;
32	
33	  // Resume keyword check: if text has common resume words, accept it
34	  if (text.length > 200) {
35	    const lower = text.toLowerCase();
36	    const resumeKeywords = ["experience", "education", "skills", "email", "phone", "university",
37	      "bachelor", "master", "engineer", "developer", "manager", "work", "project", "team"];
38	    const matched = resumeKeywords.filter(k => lower.includes(k)).length;
39	    if (matched >= 3) return true;
40	  }
41	
42	  return wordRatio > 0.3 && words.length > 10;
43	}
