100	function extractDocxFallback(bytes: Uint8Array): string {
101	  const raw = new TextDecoder("utf-8", { fatal: false }).decode(bytes);
102	  const chunks: string[] = [];
103	  const textRegex = /<w:t[^>]*>([^<]+)<\/w:t>/g;
104	  let match;
105	  while ((match = textRegex.exec(raw)) !== null) {
106	    if (match[1].trim()) chunks.push(match[1]);
107	  }
108	  if (chunks.length > 0) return chunks.join(" ").slice(0, 15000);
109	
110	  const anyTextRegex = />([^<]{3,})</g;
111	  while ((match = anyTextRegex.exec(raw)) !== null) {
112	    const text = match[1].trim();
113	    if (text.length > 3 && /[a-zA-Z]/.test(text) && !text.startsWith("xmlns")) {
114	      chunks.push(text);
115	    }
116	  }
117	  return chunks.join(" ").slice(0, 15000);
118	}
