124	    .replace(/\{\\[^{}]*\}/g, "")
125	    .replace(/\\[a-z]+\d*\s?/g, " ")
126	    .replace(/[{}\\]/g, "")
127	    .replace(/\s+/g, " ")
128	    .trim();
129	  return text.slice(0, 15000);
130	}
