287	function nameFromFilename(filename: string): string | null {
288	  if (!filename) return null;
289	  let base = filename.replace(/\.[^.]+$/, "");
290	  base = base.replace(/^(resume|cv|Resume|CV)[_\-\s]*/i, "");
291	  base = base.replace(/[_\-\s]*(resume|cv|Resume|CV)$/i, "");
292	  base = base.replace(/[_\-]+/g, " ").trim();
293	  base = base.replace(/[a-f0-9]{8,}/gi, "").trim();
294	  base = base.replace(/\([^)]*\)/g, "").trim();
295	  base = base.replace(/^[\d\s\-_.]+/, "").replace(/[\d\s\-_.]+$/, "").trim();
296	  if (isHexString(base)) return null;
297	  if (base.length < 2 || !/[a-zA-Z]{2,}/.test(base)) return null;
298	  return base.split(/\s+/).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(" ");
299	}
