138	function computeNDCG(relevances: number[], k: number): number {
139	  const topK = relevances.slice(0, k);
140	  if (topK.length === 0) return 0;
141	
142	  // DCG
143	  let dcg = 0;
144	  for (let i = 0; i < topK.length; i++) {
145	    dcg += (Math.pow(2, topK[i]) - 1) / Math.log2(i + 2);
146	  }
147	
148	  // Ideal DCG
149	  const ideal = [...relevances].sort((a, b) => b - a).slice(0, k);
150	  let idcg = 0;
151	  for (let i = 0; i < ideal.length; i++) {
152	    idcg += (Math.pow(2, ideal[i]) - 1) / Math.log2(i + 2);
153	  }
154	
155	  return idcg === 0 ? 0 : dcg / idcg;
156	}
157	
158	function computeMRR(relevances: number[], threshold: number): number {
159	  for (let i = 0; i < relevances.length; i++) {
160	    if (relevances[i] >= threshold) {
161	      return 1 / (i + 1);
162	    }
163	  }
164	  return 0;
165	}
