257	    }
258	
259	    // ── Step 6: process paid status ──────────────────────────────────────────
260	    const dodoStatus = toLocalStatus(dodoPayment.status);
261	    let becamePaid = false;
262	    let finalStatus = paymentRow.status;
263	
264	    if (dodoStatus === "paid") {
