266	      const { data: paidUpdate } = await supabase
267	        .from("payments")
268	        .update({
269	          status: "paid",
270	          ...(resolvedPaymentId ? { dodo_payment_id: resolvedPaymentId } : {}),
271	          ...(resolvedSessionId ? { dodo_checkout_session_id: resolvedSessionId } : {}),
272	        })
273	        .eq("id", paymentRow.id)
274	        .neq("status", "paid")
275	        .select("id")
