326	        .from("payments")
327	        .update({ status: dodoStatus })
328	        .eq("id", paymentRow.id);
329	      finalStatus = dodoStatus;
330	    }
331	
332	    return new Response(JSON.stringify({
333	      success: true,
334	      local_payment_id: paymentRow.id,
335	      dodo_payment_id: resolvedPaymentId,
336	      checkout_session_id: resolvedSessionId,
337	      dodo_status: dodoPayment.status || null,
338	      local_status: finalStatus,
339	      credits_added: becamePaid,
340	    }), {
341	      headers: { ...corsHeaders, "Content-Type": "application/json" },
342	    });
343	
344	  } catch (err: unknown) {
345	    console.error("verify-dodo-payment error:", err);
346	    await logSystemError({
