55	      return new Response(JSON.stringify({ error: "Unauthorized" }), {
56	        status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
57	      });
58	    }
59	
60	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
61	    const body = await req.json();
62	    const { topup_amount, plan_id, return_url } = body as Record<string, unknown>;
