33	// Generate candidate available time slots for a given date
34	// based on interviewer's weekly availability minus existing interviews.
35	function generateSlots(
36	  daySlot: { start_time: string; end_time: string; timezone: string },
37	  durationMinutes: number,
38	  date: Date,
39	  existingInterviews: Array<{ scheduled_at: string; duration_minutes: number }>
40	): string[] {
41	  const [sh, sm] = daySlot.start_time.split(":").map(Number);
42	  const [eh, em] = daySlot.end_time.split(":").map(Number);
43	
44	  const startMinutes = sh * 60 + sm;
45	  const endMinutes = eh * 60 + em;
46	
47	  const slots: string[] = [];
48	  for (let min = startMinutes; min + durationMinutes <= endMinutes; min += 30) {
49	    const slotDate = new Date(date);
50	    slotDate.setUTCHours(Math.floor(min / 60), min % 60, 0, 0);
51	
52	    // Skip past slots
53	    if (slotDate <= new Date()) continue;
54	
55	    // Check for conflicts with existing interviews
56	    const hasConflict = existingInterviews.some((iv) => {
57	      const ivStart = new Date(iv.scheduled_at).getTime();
58	      const ivEnd = ivStart + iv.duration_minutes * 60_000;
59	      const slotStart = slotDate.getTime();
60	      const slotEnd = slotStart + durationMinutes * 60_000;
61	      return slotStart < ivEnd && slotEnd > ivStart;
62	    });
63	
64	    if (!hasConflict) {
65	      slots.push(slotDate.toISOString());
66	    }
67	  }
68	
69	  return slots;
70	}
