45	// ── Detect file type from magic bytes ───────────────────────
46	function detectFileType(filename: string, bytes: Uint8Array): "pdf" | "docx" | "doc" | "rtf" | "txt" | "unknown" {
47	  if (bytes.length >= 4) {
48	    if (bytes[0] === 0x25 && bytes[1] === 0x50 && bytes[2] === 0x44 && bytes[3] === 0x46) return "pdf";
49	    if (bytes[0] === 0x50 && bytes[1] === 0x4B && bytes[2] === 0x03 && bytes[3] === 0x04) return "docx";
50	    if (bytes[0] === 0x7B && bytes[1] === 0x5C && bytes[2] === 0x72 && bytes[3] === 0x74) return "rtf";
51	  }
52	  const ext = filename.toLowerCase().split(".").pop() || "";
53	  if (ext === "pdf") return "pdf";
54	  if (ext === "docx" || ext === "doc") return ext as "docx" | "doc";
55	  if (ext === "rtf") return "rtf";
56	  if (ext === "txt" || ext === "text" || ext === "md") return "txt";
57	  return "unknown";
58	}
