89	// ── DOCX extraction (lazy mammoth + XML fallback) ───────────
90	async function extractDocxText(buffer: ArrayBuffer): Promise<string> {
91	  try {
92	    const mammoth = (await import("https://esm.sh/mammoth@1.8.0")).default;
93	    const result = await mammoth.extractRawText({ arrayBuffer: buffer });
94	    return (result.value || "").trim().slice(0, 15000);
95	  } catch {
96	    return extractDocxFallback(new Uint8Array(buffer));
97	  }
