132	// ── Safe base64 encoding ────────────────────────────────────
133	function uint8ToBase64(bytes: Uint8Array): string {
134	  let binary = "";
135	  for (let i = 0; i < bytes.length; i++) {
136	    binary += String.fromCharCode(bytes[i]);
137	  }
138	  return btoa(binary);
139	}
