302	async function generateEmbedding(parsedJson: any, rawText: string): Promise<number[] | null> {
303	  try {
304	    const p = parsedJson || {};
305	    const parts: string[] = [];
306	    if (p.candidate_name) parts.push(p.candidate_name);
307	    if (p.skills_with_evidence) parts.push(`Skills: ${p.skills_with_evidence.map((s: any) => typeof s === 'string' ? s : s.skill || s.name || '').join(', ')}`);
308	    if (p.tools) parts.push(`Tools: ${p.tools.join(', ')}`);
309	    if (p.domain_experience) parts.push(`Domain: ${p.domain_experience}`);
310	    if (p.roles_with_dates) parts.push(`Roles: ${p.roles_with_dates.map((r: any) => `${r.title || r.role || ''} at ${r.company || ''}`).join('; ')}`);
311	    if (p.education) parts.push(`Education: ${p.education.map((e: any) => typeof e === 'string' ? e : `${e.degree || ''} ${e.institution || ''}`).join('; ')}`);
312	    const summary = parts.join('. ').slice(0, 4000) || rawText.slice(0, 4000);
