230	            const currentSub = (profile as any).subscription_credits ?? 0;
231	            const subDelta = plan.credits - currentSub;
232	            await supabase
233	              .from("profiles")
234	              .update({
235	                subscription_credits: plan.credits,
236	                credits: (profile.credits ?? 0) + subDelta,
237	                subscription_ends_at: endsAt.toISOString(),
238	              })
239	              .eq("user_id", profile.user_id);
240	          } else {
241	            // Plan not found — log critical error but extend subscription to avoid locking user out
242	            console.error(`Plan "${profile.plan}" not found for renewal. Subscription ${subscriptionId}`);
243	            await logSystemError({
244	              function_name: "dodo-webhook",
245	              error_type: "RENEWAL_PLAN_NOT_FOUND",
246	              severity: "critical",
247	              error_message: `Plan "${profile.plan}" not found for subscription renewal ${subscriptionId}`,
248	              user_id: profile.user_id,
249	            });
250	            const fallbackEndsAt = new Date();
251	            fallbackEndsAt.setMonth(fallbackEndsAt.getMonth() + 1);
252	            await supabase
253	              .from("profiles")
254	              .update({ subscription_ends_at: fallbackEndsAt.toISOString() })
255	              .eq("user_id", profile.user_id);
256	          }
257	        }
258	      }
259	      await markProcessed(null);
260	    } else if (
261	      eventType === "subscription.cancelled" ||
262	      eventType === "subscription_cancelled" ||
263	      eventType === "subscription.on_hold" ||
264	      eventType === "subscription.failed"
265	    ) {
266	      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
267	      if (subscriptionId) {
268	        // For on_hold/failed: downgrade immediately; for cancelled, let expiry task handle downgrade.
269	        if (eventType.includes("on_hold") || eventType.includes("failed")) {
270	          await supabase
271	            .from("profiles")
272	            .update({
273	              plan: "free",
274	              dodo_subscription_id: null,
275	              subscription_ends_at: null,
276	            })
277	            .eq("dodo_subscription_id", subscriptionId);
278	        }
279	      }
280	      await markProcessed(null);
281	    } else if (eventType === "subscription.active" || eventType === "subscription_active") {
282	      const subscriptionId = (payload["subscription_id"] as string | undefined) || null;
283	      if (subscriptionId && localPaymentId) {
284	        const { data: payment } = await supabase.from("payments").select("user_id").eq("id", localPaymentId).single();
285	        if (payment) {
286	          await supabase.from("profiles").update({ dodo_subscription_id: subscriptionId }).eq("user_id", payment.user_id);
287	          await markProcessed(payment.user_id);
288	        }
289	      }
290	    }
291	
292	    return new Response("OK", { status: 200, headers: corsHeaders });
293	  } catch (err) {
294	    console.error("dodo-webhook error:", err);
295	    await logSystemError({
296	      function_name: "dodo-webhook",
297	      error_type: "PAYMENT_ERROR",
298	      severity: "critical",
299	      error_message: errorToMessage(err),
300	      error_stack: errorToStack(err),
301	    });
302	    return new Response("Internal error", { status: 500, headers: corsHeaders });
303	  }
304	});
