60	// ── BT/ET PDF text extraction ───────────────────────────────
61	function extractPdfText(bytes: Uint8Array): string {
62	  const raw = new TextDecoder("latin1").decode(bytes);
63	  const textChunks: string[] = [];
64	  const btEtRegex = /BT\s([\s\S]*?)ET/g;
65	  let block;
66	  while ((block = btEtRegex.exec(raw)) !== null) {
67	    const parenRegex = /\(([^)]*)\)/g;
68	    let match;
69	    while ((match = parenRegex.exec(block[1])) !== null) {
70	      const decoded = match[1]
71	        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
72	        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
73	      if (decoded.trim()) textChunks.push(decoded);
74	    }
75	    const tjRegex = /\[([^\]]*)\]\s*TJ|(\([^)]*\))\s*Tj/g;
76	    let tjMatch;
77	    while ((tjMatch = tjRegex.exec(block[1])) !== null) {
78	      const content = tjMatch[1] || tjMatch[2] || "";
79	      const innerParen = /\(([^)]*)\)/g;
80	      let ip;
81	      while ((ip = innerParen.exec(content)) !== null) {
82	        if (ip[1].trim()) textChunks.push(ip[1]);
83	      }
84	    }
85	  }
86	  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 15000);
87	}
