256	function isHexString(str: string): boolean {
257	  const cleaned = str.replace(/[\s\-_().]/g, '');
258	  if (cleaned.length < 4) return false;
259	  const hexChars = cleaned.replace(/[^a-fA-F0-9]/g, '').length;
260	  return hexChars / cleaned.length > 0.5;
261	}
