263	function isValidName(name: string | null | undefined): boolean {
264	  if (!name) return false;
265	  const lower = name.toLowerCase().trim();
266	  if (lower === "" || lower === "unknown candidate" || lower === "unknown" || lower === "n/a" || lower === "null") return false;
267	  if (isHexString(name)) return false;
268	  // Reject timestamps
269	  if (/^\d{10,}$/.test(name.trim())) return false;
270	  return true;
271	}
