273	function extractNameFromText(text: string): string | null {
274	  if (!text) return null;
275	  const lines = text.split('\n').slice(0, 5).map(l => l.trim()).filter(l => l.length > 0);
276	  for (const line of lines) {
277	    if (line.includes('@') || line.includes('http') || /^\d{3}/.test(line)) continue;
278	    if (/^(resume|curriculum|cv|objective|summary|profile|contact)/i.test(line)) continue;
279	    const words = line.split(/\s+/).filter(w => w.length > 1);
280	    if (words.length >= 2 && words.length <= 4 && words.every(w => /^[A-Z][a-zA-Z'-]+$/.test(w))) {
281	      return words.join(' ');
282	    }
283	  }
284	  return null;
285	}
