371	        const fileType = detectFileType(resume.filename, bytes);
372	        console.log(`Resume ${resume_id}: type=${fileType}, size=${bytes.length} bytes`);
373	
374	        // ── Try lightweight extraction first ──
375	        switch (fileType) {
376	          case "pdf": {
377	            // Try BT/ET extraction
378	            const btEtText = extractPdfText(bytes);
379	            if (btEtText.trim().length > 50 && isQualityText(btEtText)) {
380	              rawText = btEtText;
381	              extractionMethod = "bt_et";
382	              console.log(`Resume ${resume_id}: BT/ET good quality (${rawText.length} chars)`);
383	            }
384	
385	            // If lightweight fails, use Gemini (PRIMARY method for PDFs)
386	            if (!rawText || !isQualityText(rawText)) {
387	              console.log(`Resume ${resume_id}: using Gemini for extraction...`);
388	              const geminiResult = await extractWithGemini(bytes, resume_id, "application/pdf");
389	              if (geminiResult) {
390	                rawText = geminiResult.text;
391	                parsedJson = geminiResult.parsed;
392	                extractionMethod = "gemini_ocr";
393	                console.log(`Resume ${resume_id}: Gemini extracted ${rawText.length} chars`);
394	              }
395	            }
396	
397	            if (!rawText || rawText.trim().length < 30) {
398	              extractionFailed = true;
399	              console.error(`All extraction failed for PDF resume ${resume_id}`);
400	            }
401	            break;
402	          }
403	
404	          case "docx": {
405	            rawText = await extractDocxText(buffer);
406	            extractionMethod = "mammoth";
407	            if (!rawText || rawText.trim().length < 20) {
408	              // Try Gemini for DOCX too
409	              const geminiResult = await extractWithGemini(bytes, resume_id,
410	                "application/vnd.openxmlformats-officedocument.wordprocessingml.document");
411	              if (geminiResult) {
412	                rawText = geminiResult.text;
413	                parsedJson = geminiResult.parsed;
414	                extractionMethod = "gemini_docx";
415	              } else {
416	                extractionFailed = true;
417	              }
418	            }
419	            break;
420	          }
421	
422	          case "doc": {
423	            // Binary .doc — go straight to Gemini
424	            const geminiResult = await extractWithGemini(bytes, resume_id, "application/msword");
425	            if (geminiResult) {
426	              rawText = geminiResult.text;
427	              parsedJson = geminiResult.parsed;
428	              extractionMethod = "gemini_doc";
429	            } else {
430	              extractionFailed = true;
431	            }
432	            break;
433	          }
434	
435	          case "rtf": {
436	            rawText = extractRtfText(bytes);
437	            extractionMethod = "rtf_parser";
438	            if (!rawText || rawText.trim().length < 20) extractionFailed = true;
439	            break;
440	          }
441	
442	          case "txt": {
443	            rawText = new TextDecoder("utf-8", { fatal: false }).decode(bytes).slice(0, 15000);
444	            extractionMethod = "plaintext";
445	            break;
446	          }
447	
448	          default: {
449	            const textAttempt = new TextDecoder("utf-8", { fatal: false }).decode(bytes).slice(0, 15000);
450	            const printableRatio = textAttempt.replace(/[^\x20-\x7E\n\r\t]/g, "").length / textAttempt.length;
451	            if (printableRatio > 0.8 && textAttempt.trim().length > 50) {
452	              rawText = textAttempt;
453	              extractionMethod = "plaintext_fallback";
454	            } else {
455	              const geminiResult = await extractWithGemini(bytes, resume_id, "application/octet-stream");
456	              if (geminiResult) {
