462	              }
463	            }
464	            break;
465	          }
466	        }
467	      } else {
468	        extractionFailed = true;
469	        console.error(`Failed to download file for resume ${resume_id}`);
470	      }
471	    } else {
472	      // No file_path — use existing parsed_text if available
473	      rawText = resume.parsed_text;
474	      if (rawText && rawText.trim().length > 30) {
475	        extractionMethod = "existing_text";
476	      } else {
477	        extractionFailed = true;
478	      }
479	    }
480	
481	    // ── Determine best candidate name ──
482	    let bestName = resume.candidate_name;
483	    if (parsedJson && isValidName(parsedJson.candidate_name)) {
484	      bestName = parsedJson.candidate_name;
485	    } else if (!isValidName(bestName) && rawText) {
486	      bestName = extractNameFromText(rawText) || nameFromFilename(resume.filename) || bestName;
487	    }
